      storyPanels,
      featGroups, featImg, featSlug: cur[0].toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-$/, ''), featTag: cur[1], featCount: String(fsel + 1).padStart(2,'0') + ' / 09',
